def find(n): return next(m for m in M if m["id"] == n)
if __name__ == "__main__":
    cmd = sys.argv[1]
    if cmd == "list":
        for m in M: print(m["id"], m["title"])
    elif cmd == "apply":
        m = find(int(sys.argv[2]))
        for f, old, new in m["edits"]:
            p = os.path.join(W, f); s = open(p).read()
            assert s.count(old) == 1, (f, s.count(old), old[:60])
            open(p, "w").write(s.replace(old, new))
        print(json.dumps({"files": sorted({f for f, _, _ in m["edits"]}), "targets": m["targets"], "tests": m["tests"], "title": m["title"], "expect_build_failure": m.get("expect_build_failure", False)}))
    elif cmd == "check":
        # every anchor present exactly once in the clean tree
        bad = 0
        for m in M:
            for f, old, new in m["edits"]:
                s = open(os.path.join(W, f)).read(); c = s.count(old)
                if c != 1: bad += 1; print("ANCHOR", m["id"], f, c, repr(old[:70]))
        print("anchors bad:", bad)
